    enabled = true
  }

  logging {
    target_bucket = "log-bucket-name" # Replace with a valid logging bucket
    target_prefix = "logs/"
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm     = "aws:kms"
        kms_master_key_id = "arn:aws:kms:region:account-id:key/key-id" # Replace with a valid KMS key ARN
