resource "azurerm_storage_account" "notification_storage" {
  name                     = "smartgridscada${random_string.suffix.result}"
  resource_group_name      = azurerm_resource_group.smart_grid_rg.name
  location                 = azurerm_resource_group.smart_grid_rg.location
  account_tier             = "Standard"
  account_replication_type = "GRS" # Changed from LRS to GRS for geo-redundancy
  enable_https_traffic_only = true # Enforce HTTPS traffic only

  allow_blob_public_access = false # Disallow public access to blobs
  min_tls_version          = "TLS1_2" # Enforce the latest TLS version
  shared_access_key_enabled = false # Disable Shared Key authorization

  blob_properties {
    delete_retention_policy {
      days = 7 # Enable soft-delete with a retention period of 7 days
    }
  }

  network_rules {
    default_action = "Deny" # Deny public network access
    bypass         = ["AzureServices"]
  }

  logging {
    delete                = true # Enable logging for delete requests
    read                  = true # Enable logging for read requests
    write                 = true # Enable logging for write requests
    version               = "1.0"
    retention_policy_days = 7 # Retain logs for 7 days
  }

  private_endpoint_connection {
    name = "example-private-endpoint"
    private_service_connection {
      is_manual_connection = false
      private_connection_resource_id = azurerm_private_endpoint.example.id
    }
  }
}

