resource "google_sql_database_instance" "operational_database" {
  name             = "autonomous-drone-delivery-management-platform-sql-operational"
  database_version = "POSTGRES_14"
  region           = var.region
  settings {
    tier = var.database_tier
    ip_configuration {
      ipv4_enabled = false
      authorized_networks {
        value = "10.0.0.0/16"
        name  = "internal-network"
      }
      require_ssl = true
    }
    backup_configuration {
      enabled                        = true
      start_time                     = "03:00"
      point_in_time_recovery_enabled = true
    }
    database_flags {
      name  = "log_statement"
      value = "all"
    }
    database_flags {
      name  = "log_checkpoints"
      value = "on"
    }
    database_flags {
      name  = "log_connections"
      value = "on"
    }
    database_flags {
      name  = "log_disconnections"
      value = "on"
    }
    database_flags {
      name  = "log_lock_waits"
      value = "on"
    }
    database_flags {
      name  = "log_duration"
      value = "on"
    }
  }
  deletion_protection = false
}

resource "google_sql_database_instance" "metadata_database" {
